function safeJsonParse(x) {
  if (x === null || x === undefined) return x;
  if (typeof x === 'object') return x;
  const s = (Buffer.isBuffer?.(x) ? x.toString('utf8') : String(x));
  try { return JSON.parse(s); } catch (e) { return s; }
}

const topic = $json.topic || '';
const message = safeJsonParse($json.message);

// UNS topic: uns/<tenant>/<site>/<area>/<asset>/<stream>
const parts = topic.split('/');
let tenant = null, site = null, area = null, asset = null, stream = null;
if (parts.length >= 6 && parts[0] === 'uns') {
  tenant = parts[1];
  site   = parts[2];
  area   = parts[3];
  asset  = parts[4];
  stream = parts.slice(5).join('/');
}

const p = (typeof message === 'object' && message) ? message : { raw: message };

const eventType = p.type || (stream === 'telemetry' ? 'telemetry' : (stream === 'status' ? 'status' : 'event'));
const severity  = p.severity || 'info';
const source    = p.source || 'mqtt';
const traceId   = p.traceId || p.trace_id || null;

return [{
  json: {
    topic,
    tenant: tenant || (p.tags?.tenant ?? 'unknown'),
    site: site || (p.tags?.site ?? null),
    area: area || (p.tags?.area ?? null),
    asset: asset || (p.tags?.asset ?? null),
    stream,
    event_type: eventType,
    severity,
    source,
    trace_id: traceId,
    payload: p
  }
}];
